// ---------- v62: tài khoản nhận tiền của cán bộ (Quản trị › Cấu hình) + cán bộ tự xác nhận ----------
let TKN = null;
const TT_TKN = { 'Chờ cán bộ xác nhận': 'cho', 'Cán bộ đã xác nhận': 'ok', 'Cán bộ báo sai': 'sai', 'Đã tắt': 'tat' };
function taiTKN() {
  goiNB('admDsTKNhan').then(r => { TKN = r;
    const kh = { da: ['xanh', 'Đã khóa vân tay – khách đang thấy QR'], lech: ['do', 'LỆCH vân tay – QR đang ẩn'], chua: ['vang', 'Chưa khóa vân tay – nhắn Claude "update QR"'], khac: ['xam', 'QR không hiện'] };
    $('tknDs').innerHTML = r.ds.length ? r.ds.map(x => { const k = x.tt === 'Cán bộ đã xác nhận' ? kh[x.khoa] : kh.khac;
      return `<div class="tkn-dong tt-${TT_TKN[x.tt] || 'tat'}"><div class="tkn-tt"><b>${esc(x.canbo)}</b><span>${esc(x.nhTen)} · ${esc(x.stk)} · ${esc(x.chuChuan)}${x.khop ? '' : ' <em class="chu-do">(khác tên cán bộ)</em>'}</span>
        <small>${esc(x.tt)}${x.xn ? ' lúc ' + esc(x.xn) : ''} · nhập bởi ${esc(x.nguoi)} ${esc(x.tg)}</small><span class="tkn-nhan ${k[0]}">${esc(k[1])}</span></div>
        ${x.tt !== 'Đã tắt' ? `<button type="button" class="nut phu nho-nut" data-tat="${x.dong}">Tắt</button>` : ''}</div>`; }).join('') : '<div class="nho">Chưa có tài khoản nào – khách vẫn liên hệ cán bộ qua Zalo / gọi như trước.</div>';
    $$('#tknDs [data-tat]').forEach(b => b.onclick = () => { if (!confirm('Tắt tài khoản này? Khách sẽ không còn thấy mã QR của cán bộ.')) return; b.disabled = true; goiNB('admTatTKNhan', Number(b.dataset.tat)).then(() => { baoNhanh('Đã tắt.'); taiTKN(); }).catch(e => { b.disabled = false; $('loiTKN').textContent = e; }); });
    if ($('tknCB').options.length !== r.canBo.length + 1) $('tknCB').innerHTML = '<option value="">– Chọn cán bộ –</option>' + r.canBo.map(t => `<option>${esc(t)}</option>`).join('');
    if ($('tknNH').options.length !== r.nh.length + 1) $('tknNH').innerHTML = '<option value="">– Chọn ngân hàng –</option>' + r.nh.slice().sort((a, b) => a[1].localeCompare(b[1])).map(([b, t]) => `<option value="${esc(b)}">${esc(t)}</option>`).join('');
  }).catch(e => $('tknDs').innerHTML = `<div class="loi">${esc(e)}</div>`);
}
const khacTenTKN = () => { const cb = $('tknCB').value, chu = $('tknChu').value; const khac = !!(cb && chu.trim().length > 3 && chuanChuJS(cb) !== chuanChuJS(chu)); $('tknKhacL').classList.toggle('an', !khac); if (!khac) $('tknKhac').checked = false; return khac; };
$('tknCB').onchange = khacTenTKN; $('tknChu').oninput = khacTenTKN;
$('fTKN').onsubmit = e => {
  e.preventDefault(); $('loiTKN').textContent = '';
