    <div class="tkn-cho-tk"><span>Ngân hàng</span><b>${esc(t.nh)}</b><span>Số tài khoản</span><b>${esc(t.stk)}</b><span>Chủ tài khoản</span><b>${esc(t.chu)}</b></div>
    <div class="nho">Mở app ngân hàng của anh/chị để so từng số. Đúng mới bấm <b>Đúng</b> (phải nhập lại mật khẩu). Sai → bấm <b>Không phải của tôi</b>, quản trị được báo ngay.</div>
    <div class="hang"><button type="button" class="nut" id="tknDung">${ic('checkCircle')} Đúng tài khoản của tôi</button><button type="button" class="nut phu" id="tknSai">Không phải của tôi</button></div><div class="loi" id="loiTKCho"></div>`;
  const tl = dung => { $('tknDung').disabled = $('tknSai').disabled = true;
    goiNB('cbXacNhanTKNhan', t.dong, dung).then(() => { el.innerHTML = dung ? '<b>✓ Đã xác nhận.</b> Quản trị sẽ khóa vân tay – sau đó khách mới thấy mã QR của anh/chị.' : '<b>Đã báo quản trị</b> – tài khoản này sẽ không được dùng.'; setTimeout(() => el.classList.add('an'), 9000); })
      .catch(e => { $('loiTKCho').textContent = e; $('tknDung').disabled = $('tknSai').disabled = false; }); };
  $('tknDung').onclick = () => tl(true); $('tknSai').onclick = () => tl(false);
}
